def get_star_catalog() -> List[PlayerRecord]:
    """Returns PlayerRecord instances for all built-in FM26 star players."""
    return [
        PlayerRecord(
            uid=row[0],
            display_name=row[1],
            full_name=row[2],
            short_name=row[3],
            birth_year=row[4],
            ca=row[5],
            pa=row[6],
            current_rep=row[7],
            home_rep=row[8],
            world_rep=row[9],
            positions=list(row[10]),
            raw_attributes=list(row[11]),
        )
        for row in STAR_CATALOG_DATA
    ]
